<script setup>
import {ref,computed,onMounted} from 'vue';import {withBase} from 'vitepress';import catalog from '../../../../data/catalog.json';
const region=ref(''),query=ref('');
onMounted(()=>{const r=new URLSearchParams(location.search).get('region');if(r in catalog.regions)region.value=r;});
const filtered=computed(()=>catalog.schools.filter(s=>(!region.value||s.region===region.value)&&(!query.value||`${s.name} ${s.school_name_en} ${s.id}`.toLowerCase().includes(query.value.toLowerCase()))));
</script>
<template><div class="app-page"><header class="page-intro"><div class="eyebrow">SCHOOL DIRECTORY</div><h1>院校导航<span class="count-badge">{{catalog.schools.length}}</span></h1><p>一校一份完整报告。从你感兴趣的大学开始，了解项目之间的差异。</p></header><div class="filter-bar"><label class="search-field"><span>⌕</span><input v-model="query" aria-label="搜索大学" placeholder="搜索大学中文名、英文名…"></label><label class="select-field"><span>地区</span><select v-model="region"><option value="">全部地区</option><option v-for="(n,id) in catalog.regions" :value="id">{{n}}</option></select></label></div><div class="result-summary">找到 {{filtered.length}} 所大学 <button v-if="query||region" @click="query='';region=''" class="text-button">重置筛选</button><span>按资料索引排列，无院校排名</span></div><div class="school-grid"><article class="school-card" v-for="s in filtered" :key="s.id"><div class="school-card-top"><span>{{s.regionName}}</span><span class="badge">{{s.report_status==='reviewed'?'已人工复核':s.report_status==='needs_update'?'需更新':'调研草稿'}}</span></div><a :href="withBase(s.path)"><h2>{{s.name}}</h2><p class="english-name">{{s.school_name_en}}</p></a><div class="school-count"><strong>{{s.count}}</strong> 项目 / 培养方向条目</div><div class="school-meta">参考入学年 {{s.reference_intake_years.join(' / ')}}<br>原报告核验 {{s.last_verified_on}}</div><div class="school-links"><a :href="withBase(s.path)">阅读报告 ↗</a><a v-if="s.pdf" :href="withBase(s.pdf)" target="_blank" rel="noopener">PDF ↗</a><a :href="withBase(s.md)" download>MD ↓</a></div></article></div><div v-if="!filtered.length" class="empty-state"><h2>没有找到匹配大学</h2><p>试试缩短关键词，或选择全部地区。</p></div></div></template>
